import chardet
# Constants
API_URL = "http://api.example.com/data"
def task_func(url=API_URL, from_encoding=None, to_encoding="utf8"):
    response = requests.get(url, timeout=5)
    content = response.content

    if not content:
        return {}

    if from_encoding is None:
        detected = chardet.detect(content)
        encoding = detected.get('encoding')
        if encoding is None:
            raise ValueError("Unable to detect encoding for non-empty content")
    else:
        encoding = from_encoding

    decoded_text = content.decode(encoding)
    re_encoded_bytes = decoded_text.encode(to_encoding)

    return json.loads(re_encoded_bytes.decode(to_encoding))

import socket
import select
import queue
from datetime import datetime, timedelta

def task_func(
    server_address="localhost", server_port=12345, buffer_size=1024, run_duration=5
):
    """
    Run a non-blocking echo server that appends the server's current time to received data
    and sends it back to the client, while handling exceptional conditions for each socket.

    Args:
        server_address: The address to bind the server to.
        server_port: The port to bind the server to.
        buffer_size: The buffer size for receiving data.
        run_duration: How long to run the server in seconds.

    Returns:
        str: A status message indicating the server's operation and run duration.
    """
    # Create a server socket
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
    server_socket.bind((server_address, server_port))
    server_socket.listen(5)
    server_socket.setblocking(False)

    # Initialize select inputs
    inputs = [server_socket]
    outputs = []
    message_queues = {}

    start_time = datetime.now()
    end_time = start_time + timedelta(seconds=run_duration)

    try:
        while datetime.now() < end_time:
            # Calculate timeout for select
            now = datetime.now()
            timeout = (end_time - now).total_seconds()
            if timeout <= 0:
                break

            # Use select to monitor sockets
            readable, writable, exceptional = select.select(inputs, outputs, inputs, timeout)

            for s in readable:
                if s is server_socket:
                    # Accept new connection
                    try:
                        client_socket, client_address = server_socket.accept()
                        client_socket.setblocking(False)
                        inputs.append(client_socket)
                        message_queues[client_socket] = queue.Queue()
                    except Exception:
                        pass
                else:
                    # Handle data from client
                    try:
                        data = s.recv(buffer_size)
                        if data:
                            # Append current time to received data
                            current_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
                            response = data + f" [Server time: {current_time}]".encode()
                            message_queues[s].put(response)
                            if s not in outputs:
                                outputs.append(s)
                        else:
                            # Client disconnected
                            if s in outputs:
                                outputs.remove(s)
                            inputs.remove(s)
                            s.close()
                            del message_queues[s]
                    except Exception:
                        if s in outputs:
                            outputs.remove(s)
                        inputs.remove(s)
                        s.close()
                        if s in message_queues:
                            del message_queues[s]

            for s in writable:
                try:
                    if s in message_queues:
                        try:
                            next_msg = message_queues[s].get_nowait()
                        except queue.Empty:
                            outputs.remove(s)
                        else:
                            s.send(next_msg)
                except Exception:
                    if s in outputs:
                        outputs.remove(s)
                    if s in inputs:
                        inputs.remove(s)
                    s.close()
                    if s in message_queues:
                        del message_queues[s]

            for s in exceptional:
                inputs.remove(s)
                if s in outputs:
                    outputs.remove(s)
                s.close()
                if s in message_queues:
                    del message_queues[s]
    finally:
        # Clean up
        for s in inputs:
            if s is not server_socket:
                s.close()
        server_socket.close()

    duration = (datetime.now() - start_time).total_seconds()
    return f"Server ran for {duration:.2f} seconds"

import re
from urllib.parse import urlparse
from bs4 import BeautifulSoup
import requests

def task_func(myString):
    # Extract URL from the string
    url_pattern = re.compile(
        r'https?://[^\s<>"{}|\\^`\[\]]+'
    )
    match = url_pattern.search(myString)

    if not match:
        return "No valid URL found in the provided string."

    url = match.group(0)

    # Validate URL structure
    try:
        result = urlparse(url)
        if not all([result.scheme, result.netloc]):
            return "No valid URL found in the provided string."
    except Exception:
        return "No valid URL found in the provided string."

    # Fetch the webpage
    try:
        response = requests.get(url, timeout=10)
        response.raise_for_status()
    except requests.RequestException:
        return f"Unable to fetch the content of the URL: {url}"

    # Parse HTML and extract title
    try:
        soup = BeautifulSoup(response.text, 'html.parser')
        title_tag = soup.find('title')
        if title_tag:
            return title_tag.get_text()
        else:
            return "No title tag found in the webpage."
    except Exception:
        return "No title tag found in the webpage."

