import glob

def task_func(my_list, file_dir='./data_files/', file_ext='.csv'):
    if not isinstance(my_list, list):
        raise TypeError("my_list must be a list")

    # Add the element '12' to the list
    my_list.append('12')

    # Calculate the sum of numbers in the list
    # We need to convert elements to numbers. The problem says "sum of the numbers in the list"
    # After appending '12', the list contains original elements plus '12'
    # We need to sum all numeric values in the list
    total = 0
    for item in my_list:
        try:
            total += int(item)
        except (ValueError, TypeError):
            try:
                total += float(item)
            except (ValueError, TypeError):
                pass

    # Get all CSV files in the directory
    pattern = os.path.join(file_dir, f'*{file_ext}')
    files = glob.glob(pattern)

    if not files:
        raise FileNotFoundError(f"No files found in the specified directory: {file_dir}")

    # Sort files to have a deterministic order
    files.sort()

    # Determine how many files to concatenate
    num_files = int(total)

    # If num_files is 0 or negative, return empty DataFrame
    if num_files <= 0:
        return pd.DataFrame()

    # Select the first num_files files
    selected_files = files[:num_files]

    # If there are fewer files than requested, use all available files
    if len(selected_files) < num_files:
        selected_files = files

    # Concatenate all selected CSV files into a single DataFrame
    dfs = []
    for file in selected_files:
        try:
            df = pd.read_csv(file)
            dfs.append(df)
        except Exception:
            continue

    if not dfs:
        return pd.DataFrame()

    result = pd.concat(dfs, ignore_index=True)
    return result

