import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    """
    Executes a given bash script and returns the CPU and memory usage of the script's process.

    Args:
        script_path: Path to the bash script to execute.
        timeout: Maximum time in seconds to wait for the script to complete.

    Returns:
        A dictionary containing:
        'CPU Usage': The accumulated CPU usage in percentage.
        'Memory Usage': The accumulated memory usage in bytes.
    """
    # Check if the script path exists
    if not os.path.exists(script_path):
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    # Start the subprocess
    try:
        proc = subprocess.Popen(
            ['bash', script_path],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE
        )
    except Exception:
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    cpu_usage = 0.0
    memory_usage = 0
    start_time = time.time()

    try:
        ps_proc = psutil.Process(proc.pid)
    except (psutil.NoSuchProcess, psutil.AccessDenied):
        # Process already exited or not accessible
        try:
            proc.wait(timeout=0)
        except Exception:
            pass
        return {'CPU Usage': 0.0, 'Memory Usage': 0}

    prev_cpu_times = None
    prev_memory_info = None

    while True:
        # Check if timeout has been reached
        elapsed = time.time() - start_time
        if elapsed > timeout:
            # Terminate the process
            try:
                proc.terminate()
                proc.wait(timeout=1)
            except Exception:
                try:
                    proc.kill()
                    proc.wait(timeout=1)
                except Exception:
                    pass
            break

        # Check if process is still running
        if proc.poll() is not None:
            # Process has exited
            break

        try:
            # Get current CPU times
            cpu_times = ps_proc.cpu_times()
            current_cpu = cpu_times.user + cpu_times.system

            # Get current memory info
            memory_info = ps_proc.memory_info()
            current_rss = memory_info.rss

            if prev_cpu_times is not None:
                # Accumulate CPU usage difference
                cpu_diff = current_cpu - prev_cpu_times
                cpu_usage += cpu_diff

            if prev_memory_info is not None:
                # Accumulate memory usage difference (only positive increments)
                mem_diff = current_rss - prev_memory_info
                if mem_diff > 0:
                    memory_usage += mem_diff

            prev_cpu_times = current_cpu
            prev_memory_info = current_rss

        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            # Process no longer accessible
            break

        # Small sleep to avoid busy waiting
        time.sleep(0.1)

    # If we never got a reading, try one last time
    if prev_cpu_times is None:
        try:
            cpu_times = ps_proc.cpu_times()
            cpu_usage = cpu_times.user + cpu_times.system
            memory_info = ps_proc.memory_info()
            memory_usage = memory_info.rss
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            pass

    # Ensure process is terminated
    try:
        if proc.poll() is None:
            proc.terminate()
            proc.wait(timeout=1)
    except Exception:
        try:
            proc.kill()
            proc.wait(timeout=1)
        except Exception:
            pass

    return {'CPU Usage': cpu_usage, 'Memory Usage': memory_usage}

