import os
import re
from pathlib import Path

def task_func(dir_path: str, predicates: list) -> dict:
    """
    Evaluates each item (files and directories) in a given directory against specified conditions.

    Parameters:
    dir_path (str): Path to the directory to evaluate.
    predicates (list): List of predicate functions or regex patterns to evaluate against item names.

    Returns:
    dict: A dictionary with directory items as keys and the results of condition checks as values.

    Raises:
    ValueError: If no valid predicates are provided.
    FileNotFoundError: If the specified directory does not exist or is not a directory.
    """
    # Check if directory exists and is a directory
    if not os.path.exists(dir_path):
        raise FileNotFoundError(f"The specified directory does not exist: {dir_path}")
    if not os.path.isdir(dir_path):
        raise FileNotFoundError(f"The specified path is not a directory: {dir_path}")

    # Deduplicate predicates
    seen = set()
    unique_predicates = []
    for pred in predicates:
        # Create a hashable representation for deduplication
        if callable(pred):
            key = id(pred)
        elif isinstance(pred, str):
            key = pred
        elif isinstance(pred, re.Pattern):
            key = pred.pattern
        else:
            key = str(pred)

        if key not in seen:
            seen.add(key)
            unique_predicates.append(pred)

    # Check if there are valid predicates
    if not unique_predicates:
        raise ValueError("No valid predicates are provided.")

    # Get all items in the directory
    try:
        items = os.listdir(dir_path)
    except PermissionError:
        raise FileNotFoundError(f"Permission denied to access directory: {dir_path}")

    result = {}
    for item in items:
        # Evaluate each predicate against the item name
        results = []
        for pred in unique_predicates:
            if callable(pred):
                try:
                    res = pred(item)
                    results.append(bool(res))
                except Exception:
                    results.append(False)
            elif isinstance(pred, str):
                # Treat string as regex pattern
                try:
                    res = re.search(pred, item)
                    results.append(bool(res))
                except re.error:
                    results.append(False)
            elif isinstance(pred, re.Pattern):
                try:
                    res = pred.search(item)
                    results.append(bool(res))
                except Exception:
                    results.append(False)
            else:
                results.append(False)

        result[item] = results

    return result

import urllib.request
import os
import csv
import collections

def task_func(url, column_name, csv_file_path):
    # Download the CSV file
    try:
        urllib.request.urlretrieve(url, csv_file_path)
    except Exception as e:
        raise e

    # Read the CSV file and count occurrences
    try:
        with open(csv_file_path, 'r', newline='', encoding='utf-8') as f:
            reader = csv.DictReader(f)
            if reader.fieldnames is None:
                # Empty file or no headers
                if column_name not in (reader.fieldnames or []):
                    os.remove(csv_file_path)
                    raise ValueError(f"The provided column_name '{column_name}' does not exist in the CSV file.")
                return {}

            if column_name not in reader.fieldnames:
                os.remove(csv_file_path)
                raise ValueError(f"The provided column_name '{column_name}' does not exist in the CSV file.")

            counter = collections.Counter()
            for row in reader:
                value = row.get(column_name, '')
                counter[value] += 1

            return dict(counter)
    finally:
        # Delete the downloaded file
        if os.path.exists(csv_file_path):
            os.remove(csv_file_path)
